                    'import io\n'
                    'import json\n'
                    'import os\n'
                    'import re\n'
                    'import sys\n'
                    'import time\n'
                    'import unicodedata\n'
                    'from collections import Counter\n'
                    'from typing import Any, Callable, Dict, Iterator, List, Optional, Tuple\n'
                    '\n'
                    'DATA_DIR = os.environ.get("PPS_DATA_DIR", "./data")\n'
                    'OUTPUT_DIR = os.environ.get("PPS_OUTPUT_DIR", "./output")\n'
                    'MODEL_DIR = os.environ.get("PPS_MODEL_DIR", "/opt/models/gemma-4-26B-A4B-it")\n'
                    '\n'
                    'ITEMS = [f"v{i}" for i in range(1, 25)]\n'
                    'EVID = [f"e{i}" for i in range(1, 25)]\n'
                    'COLUMNS = ["id"] + ITEMS + EVID\n'
                    'ABSENCE = ["v10", "v11", "v16", "v18", "v20"]          # 부재탐지 항목: 근거 문구 빈칸\n'
                    '\n'
                    'DOC_ORDER = ["공고문", "규격서", "과업지시서", "제안요청서", "예외공표서", "기타"]\n'
                    'META_FIELDS = [\n'
                    '    "적용계약법", "업무구분", "계약방법", "낙찰방법", "낙찰하한율",\n'
                    '    "배정예산금액", "입찰추정가격", "소관구분", "공동도급구성방식", "정보화사업여부",\n'
                    '    "세부품명번호목록", "제한지역코드목록", "지역제한여부", "면허업종제한목록", "업종제한여부",\n'
                    '    "조항호내용", "공고게시일자", "개찰예정일자", "긴급공고여부", "입찰방법", "조달방식",\n'
                    ']\n'
                    '\n'
                    'SEED = 20260826\n'
