                                         '    if isinstance(hit, bool):\n'
                                         '        hit = int(hit)\n'
                                         '    if isinstance(hit, str):\n'
                                         '        hit = 1 if hit.strip() in ("1", "위반", "true", "True") else 0\n'
                                         '    evidence = raw.get("근거문구")\n'
                                         '    if evidence is not None and not isinstance(evidence, str):\n'
                                         '        evidence = str(evidence)\n'
                                         '    return {"v24": {"위반여부": 1 if hit == 1 else 0, "근거문구": evidence}}\n'
                                         '\n'
