                                         "            raise ValueError('tensor parallel size must be positive')\n"
                                         '        if type(gpu_mem) not in (float, int) or not 0 < gpu_mem <= 1:\n'
                                         "            raise ValueError('gpu memory utilization must be in (0, 1]')\n"
                                         '        # Resolve all local paths before any model import or construction.\n'
                                         '        if llm is None:\n'
                                         '            model_path = _local_directory(model_dir or '
