                                         "            raise ValueError('input exceeds fixed 14848-token budget; no "
                                         "truncation performed')\n"
                                         '        return len(ids)\n'
                                         '\n'
                                         '    def chat(self, batch, schema):\n'
                                         '        if self.max_tokens != MAX_TOKENS:\n'
                                         "            raise ValueError('fixed max_tokens must remain 1536')\n"
                                         '        if not isinstance(schema, dict):\n'
                                         "            raise ValueError('structured output schema must be a "
                                         "dictionary')\n"
                                         '        # Tokenize the whole batch and check every input before invoking '
