                                         '        params = self.sampling_params_factory(\n'
                                         '            temperature=0, seed=SEED, max_tokens=MAX_TOKENS, n=1,\n'
                                         '            structured_outputs=self.structured_outputs_factory(\n'
                                         '                json=schema, disable_any_whitespace=True))\n'
                                         "        # Dicts satisfy vLLM's TokensPrompt protocol. Never call llm.chat "
                                         'here.\n'
                                         '        outputs = self.llm.generate(\n'
                                         "            [{'prompt_token_ids': list(ids)} for ids in prompt_ids],\n"
