VERSION = 'pps-integrated-v1'


def emit(event, **values):
    print(json.dumps({'event': event, **values}, ensure_ascii=False), file=sys.stderr, flush=True)


def atomic_json(path, value):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=path.parent,
                                     prefix='.pps-report-', delete=False) as stream:
        temporary = Path(stream.name)
        json.dump(value, stream, ensure_ascii=False, indent=2)
        stream.write('\n')
    temporary.replace(path)


def fingerprint(value):
    raw = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':'))
    return hashlib.sha256(raw.encode('utf-8')).hexdigest()


class TokenCounter:
    """CPU-only, exact same tokenizer path as the real vLLM runner."""
    def __init__(self, path):
        if not path or not Path(path).is_dir():
            raise ValueError('a local tokenizer directory is required')
        from transformers import AutoTokenizer
        self.tokenizer = AutoTokenizer.from_pretrained(path, local_files_only=True,
                                                       trust_remote_code=False)

    def count_tokens(self, messages):
        return len(tokenize_messages(self.tokenizer, messages))


def schema_sample(schema):
    """Mechanical mock only; never used in the real inference path."""
    if 'enum' in schema:
        choices = schema['enum']
        return next((value for value in (None, 'N', 0) if value in choices), choices[0])
    kind = schema.get('type')
    if isinstance(kind, list):
        if 'null' in kind:
            return None
        kind = kind[0]
    if kind == 'object':
        return {key: schema_sample(value) for key, value in schema['properties'].items()}
    if kind == 'array':
        return []
    if kind == 'integer':
        return 0
    if kind == 'string':
        return ''
    if kind == 'boolean':
        return False
    return None


class MockRunner:
    max_tokens = 1536
    load_seconds = 0.0

    def count_tokens(self, messages):
        # No token estimate is reported as a measured model count in mock mode.
        return 1

    def chat(self, batch, schema):
        content = json.dumps(schema_sample(schema), ensure_ascii=False)
        return [{'content': content, 'finish_reason': 'stop', 'usage': {}} for _ in batch]


class ReportingRunner:
    max_tokens = 1536

    def __init__(self, runner):
        self.runner = runner
        self.stats = {}

    def count_tokens(self, messages):
        return self.runner.count_tokens(messages)

    def chat(self, batch, schema, arm):
        stat = self.stats.setdefault(arm, {'requests': 0, 'batches': 0, 'seconds': 0.0,
            'backend_batches': 0, 'backend_errors': 0, 'isolated_single_failures': 0})
        started = time.perf_counter()
        values = self._isolated(batch, schema, arm)
        stat['seconds'] += time.perf_counter() - started
        stat['requests'] += len(batch)
        stat['batches'] += 1
        return values

    def _isolated(self, batch, schema, arm):
        stat = self.stats[arm]
        stat['backend_batches'] += 1
        try:
            values = self.runner.chat(batch, schema)
            if not isinstance(values, (list, tuple)) or len(values) != len(batch):
                raise ValueError('backend output count differs')
            if any(not isinstance(value, dict) for value in values):
                raise ValueError('backend output type differs')
            return list(values)
        except Exception as error:
            stat['backend_errors'] += 1
            if len(batch) == 1:
                stat['isolated_single_failures'] += 1
                return [{'content': '', 'finish_reason': None, 'invalid': True, 'usage': {},
                         'backend_error': type(error).__name__ + ': ' + str(error)[:240]}]
            middle = len(batch) // 2
            return self._isolated(batch[:middle], schema, arm) + self._isolated(
                batch[middle:], schema, arm)


def infer_tasks(tasks, runner, chunk, validator):
    responses = {}
    pending = list(sorted(tasks, key=str))
    attempts = 0
    for round_number in range(3):
        groups = {}
        for key in pending:
            task = tasks[key]
            schema_key = fingerprint(task['schema'])
            groups.setdefault((str(key).split('/')[0] if isinstance(key, str) else key[0], schema_key), []).append(key)
        current = []
        for (arm, _), keys in groups.items():
            schema = tasks[keys[0]]['schema']
            for offset in range(0, len(keys), chunk):
                batch_keys = keys[offset:offset + chunk]
                values = runner.chat([tasks[key]['messages'] for key in batch_keys], schema, arm)
                for key, value in zip(batch_keys, values):
                    responses[key] = value
                    if not validator(key, tasks[key], value):
                        current.append(key)
                if round_number:
                    attempts += len(batch_keys)
        pending = current
        if not pending:
            break
    return responses, {'attempts': attempts, 'unresolved': [str(key) for key in pending]}


def clean_rows(records, candidate):
    """Enforce evidence syntax, never invent a quote or change a binary verdict."""
    if set(candidate) != {record['id'] for record in records}:
        raise ValueError('output IDs differ from input IDs')
    rows = []
    removed, missing = Counter(), Counter()
    for record in records:
        row = dict(candidate[record['id']])
        if set(row) != set(baseline.COLUMNS) or row['id'] != record['id']:
            raise ValueError('49-column/identity contract failed')
        for item in baseline.ITEMS:
            if type(row[item]) is not int or row[item] not in (0, 1):
                raise ValueError('non-binary verdict')
            key = 'e' + item[1:]
            original = row[key]
            if not isinstance(original, str):
                raise ValueError('evidence must be a string')
            text = unicodedata.normalize('NFC', original)
            valid = (row[item] == 1 and item not in baseline.ABSENCE and text
                     and len(text) <= 500 and not text.startswith(('=', '+', '@'))
                     and any(text in doc['text'] for doc in record['docs']))
            row[key] = text if valid else ''
            removed[item] += int(bool(original) and not row[key])
            missing[item] += int(row[item] == 1 and item not in baseline.ABSENCE and not row[key])
        rows.append(row)
    return rows, {'removed_invalid': dict(+removed), 'positive_without_evidence': dict(+missing)}


def write_submission(rows, path):
    """Atomic CSV write; preserve input ID bytes, including non-NFC IDs."""
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', newline='', dir=path.parent,
                                     prefix='.pps-csv-', delete=False) as stream:
        temporary = Path(stream.name)
        writer = csv.DictWriter(stream, fieldnames=baseline.COLUMNS, lineterminator='\n')
        writer.writeheader()
        writer.writerows(rows)
    errors = baseline.validate_csv(str(temporary), [r['id'] for r in rows])
    if errors:
        raise ValueError('CSV contract failed: ' + '; '.join(errors[:3]))
    with temporary.open(encoding='utf-8', newline='') as stream:
        if [r['id'] for r in csv.DictReader(stream)] != [r['id'] for r in rows]:
            raise ValueError('CSV input order changed')
    temporary.replace(path)


def response_is_structurally_valid(response):
    if (not isinstance(response, dict) or response.get('finish_reason') != 'stop'
            or response.get('invalid') is True):
        return False
    content = response.get('content')
    if not isinstance(content, str) or not content.strip():
        return False
    try:
        value = json.loads(content)
    except (TypeError, ValueError, json.JSONDecodeError):
        return False
    return isinstance(value, dict)


def retry_invalid_responses(tasks, responses, runner, chunk):
    targets = [key for key in sorted(tasks) if not response_is_structurally_valid(responses[key])]
    recovered, unresolved = [], []
    for arm in pipeline.ARMS:
        arm_targets = [key for key in targets if key[0] == arm]
        for offset in range(0, len(arm_targets), chunk):
            keys = arm_targets[offset:offset + chunk]
            if not keys:
                continue
            schema = tasks[keys[0]]['schema']
            values = runner.chat([tasks[key]['messages'] for key in keys], schema)
            for key, value in zip(keys, values):
                responses[key] = value
                if response_is_structurally_valid(value):
                    recovered.append(key)
                else:
                    unresolved.append(key)
    report = {
        'attempted': len(targets),
        'targets': [arm + '/' + rid for arm, rid in targets],
        'recovered': [arm + '/' + rid for arm, rid in recovered],
        'unresolved': [arm + '/' + rid for arm, rid in unresolved],
    }
    emit('invalid_retry_complete', attempted=len(targets), recovered=len(recovered),
         unresolved=len(unresolved))
    return responses, report


def normal_coverage(ids, responses):
    failed = []
    for rid in ids:
        normal = any(response_is_structurally_valid(responses[arm, rid])
                     for arm in pipeline.ARMS)
        if not normal:
            failed.append(rid)
    if failed:
        emit('all_arms_invalid_after_retry', count=len(failed), ids=failed)
    return failed


def preflight(args):
    """Streaming public-data length audit; no Gemma/BGE weights or labels loaded."""
    started = time.perf_counter()
    counter, builder = TokenCounter(args.tokenizer_dir), FactBuilder(args.data_dir)
    seen, overflows = set(), []
    stats = {arm: {'count': 0, 'tokens': 0, 'max_tokens': 0} for arm in pipeline.ARMS}
    digest = hashlib.sha256()
    for record in baseline.iter_records(args.input, limit=args.limit):
        rid = record['id']
        if rid in seen:
            raise ValueError('duplicate input ID')
        seen.add(rid)
        prepared = {rid: pipeline.prepare_record(record, builder)}
        for (arm, _), task in pipeline.make_tasks(prepared, args.data_dir).items():
            count = counter.count_tokens(task['messages'])
            stats[arm]['count'] += 1
            stats[arm]['tokens'] += count
            stats[arm]['max_tokens'] = max(stats[arm]['max_tokens'], count)
            digest.update(fingerprint(task).encode('ascii'))
            if count > baseline.PROMPT_BUDGET:
                overflows.append({'id': rid, 'arm': arm, 'tokens': count})
        if len(seen) % 200 == 0:
            emit('preflight', records=len(seen), overflows=len(overflows),
                 seconds=round(time.perf_counter() - started, 2))
    report = {'pipeline': VERSION, 'mode': 'tokenizer-only', 'records': len(seen),
              'by_arm': stats, 'input_task_sha256': digest.hexdigest(),
              'prompt_budget': baseline.PROMPT_BUDGET, 'overflows': overflows,
              'seconds': time.perf_counter() - started,
              'gemma_calls': 0, 'status': 'PASS' if not overflows else 'FAIL'}
    atomic_json(args.report, report)
    emit('preflight_complete', **report)
    return report


def run(args, *, runner_factory=None, ranking_builder=build_rankings):
    started = time.perf_counter()
    records = list(baseline.iter_records(args.input, limit=args.limit))
    ids = [r['id'] for r in records]
    if len(set(ids)) != len(ids):
        raise ValueError('duplicate input ID')
    report = {'pipeline': VERSION, 'mode': 'mock' if args.mock else 'vllm-offline',
              'records': len(records), 'status': 'RUNNING', 'server_time_verified': False,
              'max_tokens': 1536, 'temperature': 0, 'seed': 20260826, 'thinking': False,
              'max_model_len': 16384, 'quantization': 'int8_per_channel_weight_only',
              'batch_size': args.chunk, 'invalid_retry_rounds': 2}
    if not records:
        write_submission([], args.output)
        report.update(status='PASS', total_seconds=time.perf_counter() - started, gemma_calls=0)
        atomic_json(args.report, report)
        return report
    emit('start', pipeline=VERSION, records=len(records), mock=args.mock)
    builder = FactBuilder(args.data_dir)
    prepared = {r['id']: pipeline.prepare_record(r, builder) for r in records}
    base_tasks = pipeline.make_tasks(prepared, args.data_dir)
    if args.mock:
        rankings = {rid: {'id': rid, 'query': '', 'ranked': []} for rid in ids}
        retrieval = {'mode': 'mock-empty'}
    else:
        rankings, retrieval = ranking_builder(records, builder, args.embed_dir,
            device='cpu', batch_size=24, max_length=256, top_k=10)
    report['retrieval'] = retrieval
    runner = (runner_factory(args) if runner_factory else
              MockRunner() if args.mock else VLLMRunner(args.model_dir))
    report['model_load_seconds'] = runner.load_seconds
    measured = ReportingRunner(runner)
    views, specialist_tasks, routing = integration.build_specialist_tasks(
        records, measured.count_tokens, baseline.PROMPT_BUDGET)
    selected_base = {
        key: task for key, task in base_tasks.items()
        if key[0] in ('r10', 'C24') or routing[key[1]]['use_base_b_initially']
    }
    base_responses, base_retry = infer_tasks(
        selected_base, measured, args.chunk,
        lambda key, task, response: integration.valid_base_response(task, response))
    specialist_responses, specialist_retry = infer_tasks(
        specialist_tasks, measured, args.chunk,
        lambda key, task, response: integration.valid_response(key, task, response, views))
    for rid in ids:
        key = ('B', rid)
        if key not in base_responses:
            base_responses[key] = {'content': json.dumps(schema_sample(base_tasks[key]['schema']),
                ensure_ascii=False), 'finish_reason': 'stop', 'invalid': False, 'usage': {}}
    candidate, _, _, _, details = pipeline.assemble({r['id']: r for r in records},
        prepared, base_responses, rankings, builder, data_dir=args.data_dir)
    candidate, fallback_b, specialist_details = integration.apply_specialists(
        records, candidate, views, specialist_tasks, specialist_responses, routing)
    fallback_retry = {'attempts': 0, 'unresolved': []}
    if fallback_b:
        fallback_tasks = {('B', rid): base_tasks['B', rid] for rid in fallback_b}
        fallback_responses, fallback_retry = infer_tasks(
            fallback_tasks, measured, args.chunk,
            lambda key, task, response: integration.valid_base_response(task, response))
        base_responses.update(fallback_responses)
        candidate, _, _, _, details = pipeline.assemble({r['id']: r for r in records},
            prepared, base_responses, rankings, builder, data_dir=args.data_dir)
        candidate, _, specialist_details = integration.apply_specialists(
            records, candidate, views, specialist_tasks, specialist_responses, routing)
    rows, evidence = clean_rows(records, candidate)
    write_submission(rows, args.output)
    initial_calls = len(selected_base) + len(specialist_tasks)
    retry_calls = base_retry['attempts'] + specialist_retry['attempts'] + fallback_retry['attempts']
    report.update(
        status='PASS', total_seconds=time.perf_counter() - started,
        initial_logical_calls=initial_calls,
        retry_calls=retry_calls,
        fallback_b_calls=len(fallback_b),
        gemma_calls=0 if args.mock else initial_calls + retry_calls + len(fallback_b),
        task_counts={'base': len(selected_base), 'specialist': len(specialist_tasks)},
        retry={'base': base_retry, 'specialist': specialist_retry, 'fallback_b': fallback_retry},
        by_arm=measured.stats, evidence=evidence,
        unresolved_tasks=base_retry['unresolved'] + specialist_retry['unresolved']
            + fallback_retry['unresolved'])
    atomic_json(args.report, report)
    emit('complete', status=report['status'], records=len(records),
         initial_calls=initial_calls, retry_calls=retry_calls, fallback_b=len(fallback_b))
    return report


def arguments(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--mock', action='store_true', help='mechanical test; no models')
    parser.add_argument('--preflight', action='store_true', help='local tokenizer only; no inference')
    parser.add_argument('--data-dir', default='data')
    parser.add_argument('--input')
    parser.add_argument('--output-dir', default='output')
    parser.add_argument('--output')
    parser.add_argument('--report')
    parser.add_argument('--tokenizer-dir')
    parser.add_argument('--limit', type=int)
    parser.add_argument('--chunk', type=int, default=128)
    args = parser.parse_args(argv)
    if args.chunk < 1 or (args.limit is not None and args.limit < 1):
        parser.error('chunk and limit must be positive')
    if args.mock and args.preflight:
        parser.error('mock and preflight are mutually exclusive')
    if not args.mock and not args.preflight:
        if args.limit is not None or args.input or args.output:
            parser.error('server mode always processes the full PPS input and writes submission.csv')
        names = ('PPS_DATA_DIR', 'PPS_OUTPUT_DIR', 'PPS_MODEL_DIR', 'PPS_EMBED_DIR')
        missing = [name for name in names if not os.environ.get(name)]
        if missing:
            parser.error('missing environment variables: ' + ', '.join(missing))
        args.data_dir, args.output_dir, args.model_dir, args.embed_dir = [os.environ[n] for n in names]
        for name in ('data_dir', 'model_dir', 'embed_dir'):
            if not Path(getattr(args, name)).is_dir():
                parser.error(name + ' must be an existing local directory')
    args.input = args.input or str(Path(args.data_dir) / 'test.jsonl.gz')
    args.output = args.output or str(Path(args.output_dir) / 'submission.csv')
    args.report = args.report or str(Path(args.output_dir) / 'runtime_report.json')
    data = Path(args.data_dir).resolve()
    for target in (args.output, args.report):
        resolved = Path(target).resolve()
        if resolved == data or data in resolved.parents or resolved == Path(args.input).resolve():
            parser.error('outputs must not overwrite input/data assets')
    if Path(args.report).resolve() == Path(args.output).resolve():
        parser.error('report and submission paths must differ')
    return args


def emergency_submission(args, error):
    # Last-resort validity path: preserve every organizer ID and the exact 49-column contract.
    records = list(baseline.iter_records(args.input, limit=args.limit))
    rows = []
    for record in records:
        row = {'id': record['id']}
        row.update({f'v{index}': 0 for index in range(1, 25)})
        row.update({f'e{index}': '' for index in range(1, 25)})
        rows.append(row)
    write_submission(rows, args.output)
    report = {
        'pipeline': VERSION,
        'status': 'DEGRADED_PASS',
        'records': len(rows),
        'fallback': 'emergency-zero-csv',
        'error_type': type(error).__name__,
        'error': str(error)[:2000],
    }
    atomic_json(args.report, report)
    emit('emergency_submission_written', records=len(rows),
         error_type=type(error).__name__, error=str(error)[:240])
    return report


def main(argv=None):
    # No network access, no implicit Hugging Face download, no model creation on import/spawn.
    os.environ['HF_HUB_OFFLINE'] = '1'
    os.environ['TRANSFORMERS_OFFLINE'] = '1'
    os.environ['HF_HUB_DISABLE_TELEMETRY'] = '1'
    os.environ.setdefault('TOKENIZERS_PARALLELISM', 'false')
    args = arguments(argv)
    try:
        report = preflight(args) if args.preflight else run(args)
    except Exception as error:
        if args.preflight:
            atomic_json(args.report, {'pipeline': VERSION, 'status': 'FAIL',
                                     'error_type': type(error).__name__, 'error': str(error)})
            return 1
        report = emergency_submission(args, error)
    return 0 if report['status'] in ('PASS', 'DEGRADED_PASS') else 1


if __name__ == '__main__':
    raise SystemExit(main())
